package zw.ac.msu.dzimbahub.model;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="user_actions") public class UserAction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=24) private String type; @Column(nullable=false) private Long propertyId; @Column(nullable=false,length=180) private String tenantEmail; @Column(length=180) private String landlordEmail; @Column(length=2000) private String message; private Integer rating; @Column(length=2000) private String comment; private String requestedDate; private String requestedTime; @Column(nullable=false,length=20) private String status="PENDING"; @Column(nullable=false) private Instant createdAt=Instant.now(); protected UserAction(){} public UserAction(String type,Long propertyId,String tenantEmail,String landlordEmail,String message,Integer rating,String comment,String date,String time){this.type=type;this.propertyId=propertyId;this.tenantEmail=tenantEmail;this.landlordEmail=landlordEmail;this.message=message;this.rating=rating;this.comment=comment;this.requestedDate=date;this.requestedTime=time;} public Long getId(){return id;} public String getType(){return type;} public Long getPropertyId(){return propertyId;} public String getTenantEmail(){return tenantEmail;} public String getLandlordEmail(){return landlordEmail;} public String getMessage(){return message;} public Integer getRating(){return rating;} public String getComment(){return comment;} public String getRequestedDate(){return requestedDate;} public String getRequestedTime(){return requestedTime;} public String getStatus(){return status;} public void setStatus(String s){status=s;} public Instant getCreatedAt(){return createdAt;} }
